    if (lt_utf8_last != NULL && lt_utf8_last->s == s && lt_utf8_last->byte_len == str.byte_len) {
        return lt_utf8_last;
    }
    size_t base = ((((size_t)(uintptr_t)s) >> 4) & 63u) << 2;
